import json,sqlite3,pathlib,os
root=pathlib.Path('/workspace/omega_runtime/state')
for name in ['omega.sqlite3','omega_runtime.sqlite3']:
 p=root/name
 print('DB',name,'exists',p.exists(),'bytes',p.stat().st_size if p.exists() else 0)
 if not p.exists(): continue
 con=sqlite3.connect(p); con.row_factory=sqlite3.Row
 tables=[r[0] for r in con.execute("select name from sqlite_master where type='table' order by name")]
 print('TABLES',','.join(tables))
 for t in tables:
  if t.startswith('sqlite_'): continue
  try: print('COUNT',t,con.execute(f'select count(*) from {t}').fetchone()[0])
  except Exception as e: print('COUNTERR',t,type(e).__name__)
 for t in ['task','effect','relay_ledger','epoch','frame']:
  if t in tables:
   try:
    cols=[r[1] for r in con.execute(f'pragma table_info({t})')]
    statecol='state' if 'state' in cols else ('dispatch_state' if 'dispatch_state' in cols else None)
    if statecol:
     rows=con.execute(f'select {statecol},count(*) from {t} group by {statecol} order by {statecol}').fetchall(); print('STATES',t,json.dumps([list(x) for x in rows]))
   except Exception as e: print('STATEERR',t,type(e).__name__)
 con.close()
print('OUTBOX_DIRECT',len(list((root/'outbox').glob('effect_*.json'))))
print('OUTBOX_WRAPPED',len(list((root/'outbox').glob('msg_*.json'))))
print('RELAY_RESULTS',len(list((root/'relay_results').glob('*.json'))) if (root/'relay_results').exists() else 0)
print('CURRENT_RELEASE',pathlib.Path('/workspace/omega_runtime/CURRENT_RELEASE.json').read_text() if pathlib.Path('/workspace/omega_runtime/CURRENT_RELEASE.json').exists() else 'absent')
